INSERT INTO public.club_info (id,name,motto,about,history,home_ground,training_schedule,contact_email,contact_phone,logo_url,kits_url) VALUES ('main','The Teals F.C.','Freedom, Aggression, Teamwork & Intelligent Movement','The Teals F.C. is an ambitious, modern football club founded on the principles of tactical intelligence, fearless attacking play, and collective defensive discipline. We play high-tempo football with flair and precision.','Established in 2024, The Teals F.C. rapidly evolved into a dominant local force through disciplined tactical systems and fluid tiki-taka combinations. Our identity is forged in our signature teal and black colors.','The Teals Community Arena (Capacity: 3,500)','Tuesdays & Thursdays, 5:00 PM – 7:00 PM | Saturday Matchdays','thetealsfc@gmail.com','+1 (555) 832-5732','/assets/aistudio/teals_logo_e43437ce.png','/assets/aistudio/teals_kit_c5ea6daf.png');
INSERT INTO public.league_stats (id,played,won,drawn,lost,goals_for,goals_against,goal_difference,points,position) VALUES ('main',7,5,2,0,18,6,12,17,'1st');
INSERT INTO public.announcements (id,title,text,date,author,author_role,pinned,created_at) VALUES ('ann_1','Official 2024/25 Kit & Tactical Plan Released','The club has officially presented our new matchday jerseys: the stealth Black with teal pinstripes Home Kit and the crisp White & Teal Away Kit. In addition, the coaching staff has published our master Tactical Plan covering the Ryhaan-Ayaan-Henil attacking trident.','2026-11-04','Henil','WEB HANDLER',true,'2026-11-04T12:00:00Z');
INSERT INTO public.announcements (id,title,text,date,author,author_role,pinned,created_at) VALUES ('ann_2','Matchday 8 Squad Announcement vs Crimson Rovers','Squad training concluded today at West Field Pitch 3. Full squad reported fit. Kick-off is set for Saturday 16:30 at The Teals Community Arena. All registered members are encouraged to attend.','2026-11-03','Faraz','Admin',false,'2026-11-03T12:00:00Z');
INSERT INTO public.announcements (id,title,text,date,author,author_role,pinned,created_at) VALUES ('ann_3','Team Chat Access Requests Policy','Team Chat is reserved for verified club players and staff. If you are newly registered, please notify an Admin or Web Handler to review your status and grant access.','2026-11-01','Hani','Co-Owner',false,'2026-11-01T12:00:00Z');
INSERT INTO public.transfers_news (id,type,category,title,text,image,date,badge) VALUES ('news_1','transfer-in','Transfer','Faraz Signed as Defensive Anchor & ''The Destroyer''','The club is thrilled to confirm the arrival of Faraz. Known for high energy and fearless ball recovery, Faraz will partner with Johan in central defence to lock down opponent attacks.','/assets/aistudio/faraz_42a67916.png','2026-11-02','Transfer In');
INSERT INTO public.transfers_news (id,type,category,title,text,image,date,badge) VALUES ('news_2','news','Match Analysis','Tactical Breakdown: The Ryhaan-Ayaan-Henil Attacking Connection','An in-depth look at how our front three executed Tiki-Taka combinations in the 4-1 victory. Ryhaan''s line-breaking pace coupled with Henil''s clinical box finishing proved unstoppable.','/assets/aistudio/playbook1_42ada1b2.png','2026-10-30','News');
INSERT INTO public.transfers_news (id,type,category,title,text,image,date,badge) VALUES ('news_3','transfer-in','Transfer','Hani Secures Playmaker Role as Central Midfield Engine','Hani has been handed the #8 playmaker jersey. Tasked with creative distribution and 1-2 touch quick passing to link midfield with our forwards.','/assets/aistudio/hani_161f030b.png','2026-10-25','Transfer In');
INSERT INTO public.transfers_news (id,type,category,title,text,image,date,badge) VALUES ('news_4','news','Club Update','New WADZECK Kit Sponsorship Finalized for Season 2024/25','Teals FC reveals our official front-of-shirt partner ''wadzeck''. The sharp modern branding complements our teal-and-black diamond crest.','/assets/aistudio/teals_kit_c5ea6daf.png','2026-10-20','Announcement');
