INSERT INTO public.fixtures (id,type,date,time,competition,opponent,opponent_logo,venue,status,team_score,opponent_score,outcome,scorers,assists,report) VALUES ('fix_3','result','2026-11-01',NULL,'Premier School League','Apex Warriors',NULL,'The Teals Community Arena',NULL,4,1,'W','Henil (23'', 68''), Ayaan (41''), Ryhaan (82'')','Hani (2), Faizan (1)','Dominant display from start to finish. Our defensive pair Faraz and Johan neutralized counter-attacks, while Henil bagged a brace with trademark box anticipation.');
INSERT INTO public.fixtures (id,type,date,time,competition,opponent,opponent_logo,venue,status,team_score,opponent_score,outcome,scorers,assists,report) VALUES ('fix_4','result','2026-10-24',NULL,'Premier School League','Shadow United',NULL,'Shadow Ground',NULL,2,1,'W','Henil (15''), Hani (74'')','Ryhaan (1), Ayaan (1)','Tough away match played under heavy pressure. Hani curled in the winning strike from outside the box following a tiki-taka sequence.');
INSERT INTO public.fixtures (id,type,date,time,competition,opponent,opponent_logo,venue,status,team_score,opponent_score,outcome,scorers,assists,report) VALUES ('fix_5','result','2026-10-17',NULL,'Premier School League','Lightning FC',NULL,'The Teals Community Arena',NULL,2,2,'D','Ayaan (32''), Henil (89'')','Faizan (1)','A dramatic late equalizer from Henil kept our unbeaten record intact after trailing early in the second half.');
INSERT INTO public.playbook_tactics (id,category,title,description,key_players,sheet_page,sort_order) VALUES ('play_1','Attacking System','The Ryhaan – Ayaan – Henil Connection','1. Ryhaan drives forward using pace, acceleration, and dribbling.
INSERT INTO public.playbook_tactics (id,category,title,description,key_players,sheet_page,sort_order) VALUES ('play_2','Midfield Control','Hani''s Support & Tiki-Taka Short Passing','Hani joins attacks when 3+ defenders remain behind the ball. Execute 1-touch or 2-touch quick passing combinations. Pass and immediately move to create new triangles and angles.','Hani (CM), Faizan (DM)',2,2);
INSERT INTO public.playbook_tactics (id,category,title,description,key_players,sheet_page,sort_order) VALUES ('play_3','Defensive Organisation','Faraz & Johan Partnership: Destroyer & Cover','Faraz actively and aggressively pressures the ball carrier, while Johan covers the space behind as the last line of defence. Avoid sending multiple defenders to the same opponent.','Faraz (Destroyer), Johan (Last Defender)',3,3);
INSERT INTO public.playbook_tactics (id,category,title,description,key_players,sheet_page,sort_order) VALUES ('play_4','Set Pieces','Corner Defence (Max Concentration)','Track runners, challenge aerial balls, stay aware of second balls, and clear decisively. Corner defence is a full team responsibility: everyone drops back to mark.','Goalkeeper (The Wall), Full Defensive Line',3,4);
INSERT INTO public.playbook_tactics (id,category,title,description,key_players,sheet_page,sort_order) VALUES ('play_5','Individual Skills','Dribbling Principles: Faking & Direct Runs','Faking is our top-priority technique: use body feints, direction changes, and deceptive movement. Direct runs break lines with pace. Decision making: dribbling must create an advantage; once a defender is beaten, pass cleanly.','Wingers & Midfielders',2,5);
INSERT INTO public.team_principles (num,title,description) VALUES (1,'Freedom with Responsibility','Make decisions without abandoning position unnecessarily.');
INSERT INTO public.team_principles (num,title,description) VALUES (2,'Pass and Move','Never remain stationary after making a pass.');
INSERT INTO public.team_principles (num,title,description) VALUES (3,'Support the Ball Carrier','Always provide an available passing option and open angle.');
INSERT INTO public.team_principles (num,title,description) VALUES (4,'Intelligent Dribbling','Beat defenders, then make the right decision promptly.');
INSERT INTO public.team_principles (num,title,description) VALUES (5,'Defensive Cover','When one defender presses, another must immediately cover.');
INSERT INTO public.team_principles (num,title,description) VALUES (6,'Work as a Unit','Both attacking and defending involve the entire team.');
INSERT INTO public.team_principles (num,title,description) VALUES (7,'Defend Corners Seriously','Do not give opponents easy header opportunities.');
INSERT INTO public.team_principles (num,title,description) VALUES (8,'Stay Adaptable','Adjust positioning depending on match situations and tempo.');
