INSERT INTO public.chat_messages (author_id,author_name,author_role,author_photo,text,created_at) VALUES (NULL,'Hani','Co-Owner','/assets/cards/card_hani.png','Midfield combination drills felt sharp at training today. We''ll look for quick 1-touch releases to Henil and Ryhaan early on.','2026-11-04T15:24:00.000Z');
