INSERT INTO public.staff (id,name,tag,callsign,role,department,tone,roles,description,collaboration_note,photo,icon_type,sort_order) VALUES ('staff_ryhaan','Ryhaan','@CHM | M | #A5','#A5','Chairman & Manager','Executive & Management','amber','[{"title": "Chairman", "duty": "Leads the club’s vision, makes final decisions, and represents the club internally and externally."}, {"title": "Manager", "duty": "Handles team preparation, match decisions, and overall performance."}]'::jsonb,'Leads the club’s vision, makes final decisions, and represents the club internally and externally. Handles team preparation, match decisions, and overall performance. Works closely with Web Developer/Manager Henil to supply club details and analytics for website updates.','The Chairman AKA Ryhaan works closely with @WEB to provide details and analytics for real-time site updates.','/assets/cards/card_ryhaan.png',NULL,1);
INSERT INTO public.staff (id,name,tag,callsign,role,department,tone,roles,description,collaboration_note,photo,icon_type,sort_order) VALUES ('staff_henil','HENIL','@WEB | FROST','FROST','Web Developer / Manager','Executive & Management','violet','[{"title": "Web Developer / Manager", "duty": "Have all access to The Teals F.C website. Makes changes in website."}]'::jsonb,'Have all access to The Teals F.C website. Makes changes in website. The Chairman AKA Ryhaan will help @WEB for getting the details and analytics of the Teals, so @WEB can make changes in the WEBSITE.','Full system administration and portal architecture. Direct liaison with Chairman Ryhaan.','/assets/cards/card_henil.png',NULL,2);
INSERT INTO public.staff (id,name,tag,callsign,role,department,tone,roles,description,collaboration_note,photo,icon_type,sort_order) VALUES ('staff_abhivan','ABHIVAN.P','@VCHM | BREAD','BREAD','Vice Chairman & Assistant Manager','Executive & Management','teal','[{"title": "Vice Chairman", "duty": "Supports the Chairman and steps in when needed to help oversee club operations."}, {"title": "Assistant Manager", "duty": "Supports the Manager with planning, training, and on-field leadership."}]'::jsonb,'Vice Chairman - Supports the Chairman and steps in when needed to help oversee club operations. Assistant Manager - Supports the Manager with planning, training, and on-field leadership.','Executive operational support and direct training pitch coordination.','/assets/aistudio/image_90c0c06d.png',NULL,3);
INSERT INTO public.staff (id,name,tag,callsign,role,department,tone,roles,description,collaboration_note,photo,icon_type,sort_order) VALUES ('staff_faizan','Faizan','@DRT | #A10 | CB','#A10 | CB','Director of Football','Football Operations','blue','[{"title": "Director of Football", "duty": "Oversees squad planning and recruitment, working with scouts and management."}]'::jsonb,'Director of Football - Oversees squad planning and recruitment, working with scouts and management.','Steers player acquisitions, scouting intelligence, and long-term roster development.','/assets/cards/card_faizan.png',NULL,4);
INSERT INTO public.staff (id,name,tag,callsign,role,department,tone,roles,description,collaboration_note,photo,icon_type,sort_order) VALUES ('staff_advik','Advik','@HoT | #PY10','#PY10','Head of Team (Prime)','Squad Leadership','gold','[{"title": "Head of Team", "duty": "Head of @✨Prime Team Players"}]'::jsonb,'Head of Team - Head of @✨Prime Team Players. Leads prime matchday roster standards, player focus, and tactical readiness.','Maintains prime squad focus, tactical discipline, and communication with the coaching staff.','/assets/aistudio/teals_logo_e43437ce.png','prime',5);
INSERT INTO public.staff (id,name,tag,callsign,role,department,tone,roles,description,collaboration_note,photo,icon_type,sort_order) VALUES ('staff_josiah','Josiah','@HoT | #PY8','#PY8','Head of Team (Youth)','Squad Leadership','cyan','[{"title": "Head of Team", "duty": "Head of @🔵Youth Team Players"}]'::jsonb,'Head of Team - Head of @🔵Youth Team Players. Nurtures academy talents, tactical fundamentals, and transition into senior matchday rosters.','Fosters academy progression and prepares youth players for first-team elevation.','/assets/aistudio/teals_logo_e43437ce.png','youth',6);
INSERT INTO public.staff (id,name,tag,callsign,role,department,tone,roles,description,collaboration_note,photo,icon_type,sort_order) VALUES ('staff_johan','Johan','@CAO | #A1 | GK','#A1 | GK','Chief Analysis Officer','Analysis & Performance','emerald','[{"title": "Chief Analysis Officer", "duty": "Head of Analyses the Performances and Stats of Players."}]'::jsonb,'Chief Analysis Officer - Head of Analyses the Performances and Stats of Players. Tracks metrics, tactical spacing, defensive cover, and individual match ratings.','Compiles post-match analytics, defensive heatmaps, and player performance indices.','/assets/cards/card_johan.png',NULL,7);
INSERT INTO public.staff (id,name,tag,callsign,role,department,tone,roles,description,collaboration_note,photo,icon_type,sort_order) VALUES ('staff_hanan','HANAN','@CJO','CJO','Chief Journalism Officer','Media & Journalism','rose','[{"title": "Chief Journalism Officer", "duty": "Head of Journalists, News, and Interviews."}]'::jsonb,'Chief Journalism Officer - Head of Journalists, News, and Interviews. Leads official match reports, press room briefs, locker room interviews, and media dispatches.','Directs journalism team, matchday media coverage, and player interviews.','/assets/aistudio/teals_logo_e43437ce.png','press',8);